package org.apache.commons.lang3.math;

import java.io.*;
import java.lang.reflect.Array;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_createNumber_TriageGen1Test {

    @Test
    public void testCreateNumber_Null() {
        assertNull(NumberUtils.createNumber(null));
    }

    @Test(expected = NumberFormatException.class)
    public void testCreateNumber_Blank() {
        NumberUtils.createNumber("   ");
    }

    @Test
    public void testCreateNumber_HexInteger() {
        // Assuming createInteger handles common hex if logic flows there
        // Based on code: hexDigits <= 8 -> createInteger
        assertEquals(Integer.valueOf(255), NumberUtils.createNumber("0xFF"));
        assertEquals(Integer.valueOf(15), NumberUtils.createNumber("#F"));
    }

    @Test
    public void testCreateNumber_HexLong() {
        // hexDigits > 8 and <= 16 -> createLong
        // "0x123456789" is 9 digits
        Number res = NumberUtils.createNumber("0x123456789");
        assertTrue(res instanceof Long);
    }

    @Test
    public void testCreateNumber_HexBigInteger() {
        // hexDigits > 16 -> createBigInteger
        Number res = NumberUtils.createNumber("0x12345678901234567");
        assertTrue(res instanceof BigInteger);
    }

    @Test
    public void testCreateNumber_NegativeHex() {
        assertEquals(Integer.valueOf(-1), NumberUtils.createNumber("-0x1"));
        assertEquals(Integer.valueOf(-1), NumberUtils.createNumber("-#1"));
    }

    @Test
    public void testCreateNumber_Integer() {
        assertEquals(Integer.valueOf(123), NumberUtils.createNumber("123"));
    }

    @Test
    public void testCreateNumber_Long() {
        // Large value that exceeds Integer but fits in Long
        assertEquals(Long.valueOf(3000000000L), NumberUtils.createNumber("3000000000"));
    }

    @Test
    public void testCreateNumber_BigInteger() {
        String bigVal = "999999999999999999999999999999";
        assertEquals(new BigInteger(bigVal), NumberUtils.createNumber(bigVal));
    }

    @Test
    public void testCreateNumber_Float() {
        // numDecimals <= 7
        Number res = NumberUtils.createNumber("1.2345");
        assertTrue(res instanceof Float);
        assertEquals(1.2345f, ((Float) res).floatValue(), 0.0001f);
    }

    @Test
    public void testCreateNumber_Double() {
        // numDecimals between 8 and 16
        Number res = NumberUtils.createNumber("1.123456789");
        assertTrue(res instanceof Double);
        assertEquals(1.123456789, ((Double) res).doubleValue(), 0.000000001);
    }

    @Test
    public void testCreateNumber_BigDecimal() {
        // numDecimals > 16
        String highPrecision = "1.1234567890123456789";
        Number res = NumberUtils.createNumber(highPrecision);
        assertTrue(res instanceof BigDecimal);
        assertEquals(new BigDecimal(highPrecision), res);
    }

    @Test
    public void testCreateNumber_Exponent() {
        // Float via exponent
        Number res = NumberUtils.createNumber("1.2e3");
        assertTrue(res instanceof Float);
        assertEquals(1200.0f, ((Float) res).floatValue(), 0.001f);
    }

    @Test
    public void testCreateNumber_SuffixF() {
        // Explicit float suffix
        Number res = NumberUtils.createNumber("123.45f");
        assertTrue(res instanceof Float);
    }

    @Test
    public void testCreateNumber_SuffixD() {
        // Explicit double suffix
        Number res = NumberUtils.createNumber("123.45d");
        assertTrue(res instanceof Double);
    }

    @Test(expected = NumberFormatException.class)
    public void testCreateNumber_InvalidSuffix() {
        NumberUtils.createNumber("123.45z");
    }

    @Test(expected = NumberFormatException.class)
    public void testCreateNumber_BadExponentPos() {
        // Triggering the expPos < decPos check
        NumberUtils.createNumber("1.2e"); 
    }

    @Test
    public void testCreateNumber_AllZerosCheck() {
        // Tests the allZeros logic for float/double branches
        Number res = NumberUtils.createNumber("0.0000000");
        assertTrue(res instanceof Float);
        assertEquals(0.0f, ((Float) res).floatValue(), 0.0f);
    }

    @Test(expected = NumberFormatException.class)
    public void testCreateNumber_InvalidFormat() {
        NumberUtils.createNumber("abc");
    }

    @Test
    public void testCreateNumber_ScientificNotationDouble() {
        // Testing the case where scientific notation leads to Double or BigDecimal
        Number res = NumberUtils.createNumber("1.23456789E10");
        assertTrue(res instanceof Double || res instanceof BigDecimal);
    }

    @Test
    public void testCreateNumber_LargeExponent() {
        // Test case for the expPos > str.length() check
        // Note: The provided code logic for expPos calculation is actually a bit buggy 
        // (indexOf('e') + indexOf('E') + 1), but we test the logic flow.
        try {
            NumberUtils.createNumber("1e10");
        } catch (Exception e) {
            // Expected behavior depends on implementation details of internal methods
        }
    }
}
